from rich.style import Style

def test_without_color_meta():
    style = Style(color="red", meta={"foo": "bar"})
    colorless_style = style.without_color
    print(f"Original meta: {style.meta}")
    print(f"Colorless meta: {colorless_style.meta}")
    if colorless_style.meta == style.meta:
        print("SUCCESS: Meta is preserved")
    else:
        print("BUG: Meta is lost")

if __name__ == "__main__":
    test_without_color_meta()

